// mismatch names an object by its type, which says more than "object".
func mismatch(path, want string, got vm.Value) error {
	kind := got.Kind()
	if name := got.ObjectTypeName(); name != "" {
		kind = name
	}
	return fmt.Errorf("%s: want %s, got %s", path, want, kind)
}

func unknownMember(path, typ, key string) error {
	return fmt.Errorf("%s: %s has no member %q", path, typ, key)
}

func missingMember(path, typ, key string) error {
	return fmt.Errorf("%s: field %q is missing, and a %s requires it", path, key, typ)
}

func decodeString(v vm.Value, path string) (string, error) {
	if !v.IsString() {
		return "", mismatch(path, "str", v)
	}
	return v.AsString(), nil
}

// decodeEnum accepts an enum case or its backing string: a spell writes the case, and
// the encoder writes the string. An unset Go enum crosses as null or an empty
// backing string, so both decode to its zero value.
func decodeEnum(v vm.Value, path, typ string, cases []string) (string, error) {
	if v.IsNull() || (v.IsString() && v.AsString() == "") {
		return "", nil
	}
	if backing, ok := v.EnumValue(); ok {
		v = backing
	}
	if !v.IsString() {
		return "", mismatch(path, typ, v)
	}
	s := v.AsString()
	for _, c := range cases {
		if s == c {
			return s, nil
		}
	}
	return "", fmt.Errorf("%s: %q is not a %s case", path, s, typ)
}

func decodeBool(v vm.Value, path string) (bool, error) {
	if !v.IsBool() {
		return false, mismatch(path, "bool", v)
	}
	return v.AsBool(), nil
}

func decodeInt(v vm.Value, path string) (int64, error) {
	if !v.IsInt() {
		return 0, mismatch(path, "int", v)
	}
	return v.AsInt(), nil
}

func decodeUint(v vm.Value, path string) (uint64, error) {
	if !v.IsInt() {
		return 0, mismatch(path, "int", v)
	}
	n := v.AsInt()
	if n < 0 {
		return 0, fmt.Errorf("%s: want a non-negative int, got %d", path, n)
	}
	return uint64(n), nil
}

// decodeFloat widens an int, which Buzz writes for a whole-number double literal.
func decodeFloat(v vm.Value, path string) (float64, error) {
	switch {
	case v.IsFloat():
		return v.AsFloat(), nil
	case v.IsInt():
		return float64(v.AsInt()), nil
	}
	return 0, mismatch(path, "double", v)
}

// decodeStringList decodes a [str]; an empty list is nil, like every other generated list.
func decodeStringList(v vm.Value, path string) ([]string, error) {
	items, err := decodeList(v, path, "[str]")
	if err != nil {
		return nil, err
	}
	if len(items) == 0 {
		return nil, nil
	}
	out := make([]string, len(items))
	for i, item := range items {
		s, err := decodeString(item, fmt.Sprintf("%s[%d]", path, i))
		if err != nil {
			return nil, err
		}
		out[i] = s
	}
	return out, nil
}

func decodeList(v vm.Value, path, want string) ([]vm.Value, error) {
	if !v.IsList() {
		return nil, mismatch(path, want, v)
	}
	return v.ListItems(), nil
}

// decodeMap refuses an object instance: a {str: T} field takes a map, and an object's
// members are not entries.
func decodeMap(v vm.Value, path, want string) (vm.Value, error) {
	if !v.IsMap() {
		return vm.Null, mismatch(path, want, v)
	}
	return v, nil
}

// decodeAny reads an any field as the plain Go value JSON would give it: null, bool,
// int64, float64, string, []any or map[string]any, an enum case as its backing value and
// an object instance as its members. A function or any other value JSON cannot hold is an
// error, since the field is opaque host JSON.
func decodeAny(v vm.Value, path string) (any, error) {
	if backing, ok := v.EnumValue(); ok {
		v = backing
	}
	switch {
	case v.IsNull():
		return nil, nil
	case v.IsBool():
		return v.AsBool(), nil
	case v.IsInt():
		return v.AsInt(), nil
	case v.IsFloat():
		return v.AsFloat(), nil
	case v.IsString():
		return v.AsString(), nil
	case v.IsList():
		items := v.ListItems()
		out := make([]any, len(items))
		for i, item := range items {
			x, err := decodeAny(item, fmt.Sprintf("%s[%d]", path, i))
			if err != nil {
				return nil, err
			}
			out[i] = x
		}
		return out, nil
	}
	fields, ok := v.MapView()
	if !ok {
		return nil, mismatch(path, "any JSON value", v)
	}
	keys := fields.MapKeys()
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		item, _ := fields.MapGet(key)
		x, err := decodeAny(item, fmt.Sprintf("%s[%q]", path, key))
		if err != nil {
			return nil, err
		}
		out[key] = x
	}
	return out, nil
}
